package com.opensocket.aievent.core.issuetracking.relay;
import java.time.OffsetDateTime; import java.util.Objects;
public record RelayEdge(String tenantId,String edgeId,String topologyId,String connectionId,String projectMappingId,String providerType,String externalProjectId,String sourceExternalIssueId,String targetExternalIssueId,RelayEdgeType edgeType,String relationType,String sourceMarker,RelayEdgeStatus status,int attemptCount,OffsetDateTime nextAttemptAt,String providerObjectId,String lastErrorCode,String lastErrorMessage,long version,OffsetDateTime createdAt,OffsetDateTime updatedAt,String correlationId) {
 public RelayEdge { tenantId=req(tenantId,"tenantId");edgeId=req(edgeId,"edgeId");topologyId=req(topologyId,"topologyId");connectionId=req(connectionId,"connectionId");projectMappingId=norm(projectMappingId);providerType=req(providerType,"providerType");externalProjectId=norm(externalProjectId);sourceExternalIssueId=req(sourceExternalIssueId,"sourceExternalIssueId");targetExternalIssueId=norm(targetExternalIssueId);edgeType=Objects.requireNonNull(edgeType,"edgeType is required");relationType=req(relationType,"relationType");sourceMarker=req(sourceMarker,"sourceMarker");status=Objects.requireNonNull(status,"status is required");if(attemptCount<0)throw new IllegalArgumentException("attemptCount cannot be negative");providerObjectId=norm(providerObjectId);lastErrorCode=norm(lastErrorCode);lastErrorMessage=norm(lastErrorMessage);if(version<1)throw new IllegalArgumentException("version must be positive");createdAt=Objects.requireNonNull(createdAt,"createdAt is required");updatedAt=Objects.requireNonNull(updatedAt,"updatedAt is required");correlationId=norm(correlationId); }
 private static String req(String v,String n){Objects.requireNonNull(v,n+" is required");String x=v.trim();if(x.isEmpty())throw new IllegalArgumentException(n+" is required");return x;} private static String norm(String v){return v==null?"":v.trim();}
}
